#!/bin/bash

macos_render_shell_env() {
    local quoted_brew=""
    local quoted_prefix=""
    local quoted_config=""
    local quoted_tools=""
    printf -v quoted_brew '%q' "$BREW_BIN"
    printf -v quoted_prefix '%q' "$BREW_PREFIX"
    printf -v quoted_config '%q' "$MACOS_CONFIG_DIR"
    printf -v quoted_tools '%q' "$UV_TOOL_BIN"
    cat <<EOF
# Generated by FluxEnv macOS. Custom settings: macos.local.zsh in this directory.
if [[ -o interactive && -z \${FLUXENV_MACOS_LOADED:-} ]]; then
typeset -g FLUXENV_MACOS_LOADED=1
typeset -g _fluxenv_brew=$quoted_brew
typeset -g _fluxenv_prefix=$quoted_prefix
typeset -g _fluxenv_config=$quoted_config

if [[ \${HOMEBREW_PREFIX:-} != \$_fluxenv_prefix && -x \$_fluxenv_brew ]]; then
    eval "\$(\$_fluxenv_brew shellenv)"
fi
typeset -U path fpath
path=("\$_fluxenv_prefix/bin" "\$_fluxenv_prefix/sbin" \$path)
path=($quoted_tools \$path)
[[ ! -d \$HOME/.local/bin ]] || path=("\$HOME/.local/bin" \$path)
[[ ! -d \$HOME/bin ]] || path=("\$HOME/bin" \$path)
[[ ! -d \$_fluxenv_prefix/share/zsh/site-functions ]] ||
    fpath=("\$_fluxenv_prefix/share/zsh/site-functions" \$fpath)
export PATH

export LANG="\${LANG:-en_US.UTF-8}"
export CLICOLOR=1
export LSCOLORS=ExFxBxDxCxegedabagacad
alias ls='ls -G'
alias ll='ls -lhG'
alias la='ls -lahG'
alias grep='grep --color=auto'

HISTFILE="\${HISTFILE:-\$HOME/.zsh_history}"
HISTSIZE=10000
SAVEHIST=10000
setopt EXTENDED_HISTORY SHARE_HISTORY HIST_EXPIRE_DUPS_FIRST
setopt HIST_IGNORE_ALL_DUPS HIST_FIND_NO_DUPS HIST_IGNORE_SPACE
setopt HIST_SAVE_NO_DUPS HIST_REDUCE_BLANKS

autoload -Uz compinit
compinit -d "\${ZDOTDIR:-\$HOME}/.zcompdump"
zstyle ':completion:*' menu select
zstyle ':completion:*' matcher-list 'm:{a-zA-Z}={A-Za-z}'

if [[ -r \$_fluxenv_prefix/etc/profile.d/autojump.sh ]]; then
    source "\$_fluxenv_prefix/etc/profile.d/autojump.sh"
fi
if command -v starship >/dev/null 2>&1; then
    export STARSHIP_CONFIG="\${STARSHIP_CONFIG:-\$_fluxenv_config/starship-macos.toml}"
    eval "\$(starship init zsh)"
fi
[[ ! -r \$_fluxenv_config/macos.local.zsh ]] || source "\$_fluxenv_config/macos.local.zsh"

# Terminal.app does not reliably render Starship's 24-bit colors. Set its
# ANSI palette for the current window, then let Starship use those color slots.
# Set FLUXENV_TERMINAL_THEME=none in macos.local.zsh to keep the profile colors.
if [[ "\${TERM_PROGRAM:-}" == Apple_Terminal && "\${FLUXENV_TERMINAL_THEME:-fluxenv_pro}" != none ]]; then
    printf '\033]4;0;rgb:1f/24/30\a'
    printf '\033]4;1;rgb:ff/6b/81\a'
    printf '\033]4;2;rgb:50/e3/a4\a'
    printf '\033]4;3;rgb:ff/9f/43\a'
    printf '\033]4;4;rgb:6c/b6/ff\a'
    printf '\033]4;5;rgb:d8/b4/fe\a'
    printf '\033]4;6;rgb:56/d4/dd\a'
    printf '\033]4;7;rgb:d7/de/e9\a'
    printf '\033]4;8;rgb:6b/72/80\a'
    printf '\033]4;9;rgb:ff/85/85\a'
    printf '\033]4;10;rgb:b8/f2/b0\a'
    printf '\033]4;11;rgb:ff/d9/7d\a'
    printf '\033]4;12;rgb:91/c8/ff\a'
    printf '\033]4;13;rgb:e9/c6/ff\a'
    printf '\033]4;14;rgb:7a/e8/ef\a'
    printf '\033]4;15;rgb:f3/f6/fa\a'
    printf '\033]10;rgb:f3/f6/fa\a'
    printf '\033]11;rgb:20/23/2b\a'
    printf '\033]12;rgb:7a/e8/ef\a'
fi

# Plugins run after the existing .zshrc and personal settings.
typeset -g ZSH_AUTOSUGGEST_HIGHLIGHT_STYLE='fg=8'
typeset -gA ZSH_HIGHLIGHT_STYLES
ZSH_HIGHLIGHT_STYLES[default]='fg=7'
ZSH_HIGHLIGHT_STYLES[unknown-token]='fg=1'
ZSH_HIGHLIGHT_STYLES[reserved-word]='fg=3'
ZSH_HIGHLIGHT_STYLES[precommand]='fg=2'
ZSH_HIGHLIGHT_STYLES[commandseparator]='fg=4'
ZSH_HIGHLIGHT_STYLES[path]='fg=6'
ZSH_HIGHLIGHT_STYLES[path_pathseparator]='fg=4'
ZSH_HIGHLIGHT_STYLES[single-quoted-argument]='fg=3'
ZSH_HIGHLIGHT_STYLES[double-quoted-argument]='fg=3'
ZSH_HIGHLIGHT_STYLES[dollar-quoted-argument]='fg=3'
ZSH_HIGHLIGHT_STYLES[redirection]='fg=5'
ZSH_HIGHLIGHT_STYLES[comment]='fg=8'
if [[ -r \$_fluxenv_prefix/share/zsh-autosuggestions/zsh-autosuggestions.zsh ]]; then
    source "\$_fluxenv_prefix/share/zsh-autosuggestions/zsh-autosuggestions.zsh"
fi
if [[ -r \$_fluxenv_prefix/share/zsh-syntax-highlighting/zsh-syntax-highlighting.zsh ]]; then
    source "\$_fluxenv_prefix/share/zsh-syntax-highlighting/zsh-syntax-highlighting.zsh"
fi
unset _fluxenv_brew _fluxenv_prefix _fluxenv_config
fi
true
EOF
}

macos_configure_default_shell() {
    local login_shell=""
    login_shell="$(dscl . -read "/Users/$TARGET_USER" UserShell 2>/dev/null | awk '{print $2}' || true)"
    if [ "$login_shell" = "/bin/zsh" ]; then
        progress "当前用户的默认 shell 已是 /bin/zsh"
        return 0
    fi
    if [ "$CHANGE_DEFAULT_SHELL" = "ask" ]; then
        prompt_yes_no "是否将当前用户的默认 shell 改为 macOS 自带的 zsh？" n || return 0
    elif [ "$CHANGE_DEFAULT_SHELL" -ne 1 ]; then
        return 0
    fi
    run_cmd "为当前用户设置默认 shell" chsh -s /bin/zsh
}

step_macos_shell_env() {
    stage "zsh / Starship / 插件配置"
    macos_prepare_backups
    run_cmd "创建当前用户的配置目录" mkdir -p "$MACOS_CONFIG_DIR" "$MACOS_ZDOTDIR"
    local rendered=""
    rendered="$(mktemp "${TMPDIR:-/tmp}/fluxenv-zsh.XXXXXX")"
    macos_render_shell_env > "$rendered"
    if ! /bin/zsh -n "$rendered"; then
        rm -f "$rendered"
        die "生成的 zsh 配置语法无效"
    fi
    macos_write_file "$MACOS_CONFIG_DIR/macos.zsh" macos.zsh < "$rendered"
    rm -f "$rendered"
    macos_write_file "$MACOS_CONFIG_DIR/starship-macos.toml" starship-macos.toml < "$ROOT_DIR/config/starship-macos.toml"
    if [ "$DRY_RUN" -eq 0 ]; then
        env STARSHIP_CONFIG="$MACOS_CONFIG_DIR/starship-macos.toml" \
            "$BREW_PREFIX/bin/starship" module character >/dev/null
    fi

    local quoted_brew=""
    local quoted_shell=""
    local quoted_tools=""
    local quoted_nvm=""
    local quoted_pnpm=""
    local body=""
    printf -v quoted_brew '%q' "$BREW_BIN"
    printf -v quoted_shell '%q' "$MACOS_CONFIG_DIR/macos.zsh"
    printf -v quoted_tools '%q' "$UV_TOOL_BIN"
    printf -v quoted_nvm '%q' "$NVM_DIR"
    printf -v quoted_pnpm '%q' "$PNPM_HOME"
    body="if [ -x $quoted_brew ]; then"$'\n'"    eval \"\$($quoted_brew shellenv)\""$'\n'"fi"
    macos_update_block "$MACOS_ZDOTDIR/.zprofile" '# >>> fluxenv macos >>>' '# <<< fluxenv macos <<<' "$body" zprofile
    body="$(cat <<EOF
typeset -U path
path=($quoted_tools \$path)
[ ! -r $quoted_shell ] || source $quoted_shell
export PNPM_HOME=$quoted_pnpm
[[ ! -d \$PNPM_HOME ]] || path=("\$PNPM_HOME/bin" "\$PNPM_HOME" \$path)
export NVM_DIR=$quoted_nvm
[ ! -r "\$NVM_DIR/nvm.sh" ] || source "\$NVM_DIR/nvm.sh"
nvm use --silent default >/dev/null 2>&1 || true
EOF
)"
    macos_update_block "$MACOS_ZDOTDIR/.zshrc" '# >>> fluxenv macos >>>' '# <<< fluxenv macos <<<' "$body" zshrc
    macos_configure_default_shell
}

step_macos_vim() {
    stage "Vim 配置"
    if [ "$VIM_ENABLED" -ne 1 ]; then
        progress "跳过 Vim"
        return 0
    fi
    macos_write_file "$MACOS_CONFIG_DIR/vimrc-macos" vimrc-macos <<'EOF'
" Generated by FluxEnv macOS. Uses the native macOS clipboard.
set number
set mouse=a
set smartindent
set tabstop=4
set shiftwidth=4
set expandtab
set clipboard=unnamed
syntax on
EOF
    local vim_path="$MACOS_CONFIG_DIR/vimrc-macos"
    vim_path="${vim_path//\'/\'\'}"
    macos_update_block "$MACOS_VIMRC" '" >>> fluxenv macos >>>' '" <<< fluxenv macos <<<' \
        "execute 'source ' . fnameescape('$vim_path')" vimrc
    progress "Vim 使用原生剪贴板；原有 Vim 配置和插件保留"
}
